atasetParameter": { "Id": "string", "Name": "string", "ValueType": "MULTI_VALUED"|"SINGLE_VALUED", "DefaultValues": { "StaticValues": ["string", ...] } }, "DecimalDatasetParameter": { "Id": "string", "Name": "string", "ValueType": "MULTI_VALUED"|"SINGLE_VALUED", "DefaultValues": { "StaticValues": [double, ...] } }, "IntegerDatasetParameter": { "Id": "string", "Name": "string", "ValueType": "MULTI_VALUED"|"SINGLE_VALUED", "DefaultValues": { "StaticValues": [long, ...] } }, "DateTimeDatasetParameter": { "Id": "string", "Name": "string", "ValueType": "MULTI_VALUED"|"SINGLE_VALUED", "TimeGranularity": "YEAR"|"QUARTER"|"MONTH"|"WEEK"|"DAY"|"HOUR"|"MINUTE"|"SECOND"|"MILLISECOND", "DefaultValues": { "StaticValues": [timestamp, ...] } } } ... ]
